/** Inactive role compiler through the actual native atlas, standalone media, shaders and active consumer. */
@EventBusSubscriber(modid="vandorlabs",value=Dist.CLIENT)
public final class NativeScreenRenderChecks {
 private static NativeScreenDraw[] scenes;private static NativeScreenEntity.Visual[] visuals;private static NativeScreenRenderer.Bake bake;private static final Object WORLD=new Object();private static final ScreenFamily.State STATE=new ScreenFamily.State(2,false,false,false);private static final net.minecraft.core.BlockPos[] OWNERS=new net.minecraft.core.BlockPos[16];private static int frames;private static boolean capture,done;private static int[] disabled;
 private static boolean enabled(){return "true".equals(System.getenv("VANDOR_SCREEN_RENDER_CHECK"));}
 private static void need(boolean yes,String why){if(!yes)throw new AssertionError("Screen GPU: "+why);}
 @EventBusSubscriber(modid="vandorlabs",value=Dist.CLIENT,bus=EventBusSubscriber.Bus.MOD)public static final class Shaders {@SubscribeEvent public static void shaders(RegisterShadersEvent event)throws Exception{if(enabled())NativeScreenLayers.registerShaders(event);}}
 private static NativeScreenEntity.Visual visual(ScreenFamily family,int variant){var catalog=NativeScreenCatalog.INSTANCE;var tag=NativeScreenFactory.choices(family,catalog,catalog.defaultHousing(),catalog.defaultFrame());tag.putInt("displayMode",2);tag.putInt("animationSpeedIndex",0);tag.putInt("FrameFront",variant==1?catalog.sourceChoice("frames/frames-door-window/lights-cyan-1"):-1);tag.putBoolean("FrameTile",true);if(variant==1){int custom=catalog.sourceChoice("console_inputs/console_controls_biology_controls_static");tag.putInt("PrimarySurfaceTexture",custom);tag.putInt("SecondarySurfaceTexture",custom);tag.putBoolean("DisplaySplit",family==ScreenFamily.SCREEN||family==ScreenFamily.DIAGONAL||family==ScreenFamily.INPUT);tag.putInt("DisplaySplitTop",custom);tag.putInt("DisplaySplitBottom",custom);}if(variant==2){String input="company_seyr_half_communications";tag.putString("inputPanel",input);tag.putString("secondaryInputPanel",input);if(family==ScreenFamily.INPUT)tag.putInt("PrimarySurfaceTexture",catalog.sourceChoice("console_inputs/"+input+"_static"));}tag=NativeScreenArtworkMigration.normalize(tag,catalog);var settings=NativeScreenSettings.read(tag,catalog);var frame=FrameSettings.read(new ModernHousingTags(tag),catalog::validFrame,catalog::validFrameSurface,catalog::validMaterial);var controls=List.of(new NativeScreenControls(false,"",List.of()),new NativeScreenControls(false,"",List.of()));var appearance=NativeScreenAppearance.of(family,settings,frame,controls,0,catalog);return new NativeScreenEntity.Visual(family,settings,frame,PanelPlayback.DEFAULT,controls,0,0,false,1,appearance);}
 private static void prepare(){var source=NativePanelPlaybackRenderer.currentBake();need(source!=null,"shared actual atlas bake");var materials=new NativeScreenMaterials(source,Minecraft.getInstance().getResourceManager());need(materials.input(NativeScreenMediaCatalog.input("company_seyr_half_communications")).frameCount()==6,"real layered company input has six authored frames");bake=new NativeScreenRenderer.Bake(source,Minecraft.getInstance().getResourceManager());scenes=new NativeScreenDraw[16];visuals=new NativeScreenEntity.Visual[16];var families=ScreenFamily.values();need(families.length==7,"all seven canonical roles");for(int i=0;i<16;i++){var family=i<14?families[i%7]:i==14?ScreenFamily.INPUT:ScreenFamily.HALF_INPUT;var visual=visual(family,i<7?0:i<14?1:2);visuals[i]=visual;OWNERS[i]=new net.minecraft.core.BlockPos(i,64,0);scenes[i]=bake.draw(visual,STATE,NativeScreenRenderProjection.SINGLE,WORLD,OWNERS[i]);need(scenes[i].retainedBytes()>96&&scenes[i].retainedBytes()<128*1024,"bounded authored mesh scene="+i);}need(bake.meshBuilds()==16&&bake.retainedBytes()<4*1024*1024,"bounded 16 scene cache");for(int i=0;i<10000;i++)bake.draw(visuals[0],STATE,NativeScreenRenderProjection.SINGLE,WORLD,OWNERS[0]);var bean=(com.sun.management.ThreadMXBean)java.lang.management.ManagementFactory.getThreadMXBean();if(!bean.isThreadAllocatedMemoryEnabled())bean.setThreadAllocatedMemoryEnabled(true);long before=bean.getThreadAllocatedBytes(Thread.currentThread().threadId());for(int i=0;i<10000;i++)bake.draw(visuals[0],STATE,NativeScreenRenderProjection.SINGLE,WORLD,OWNERS[0]);long allocated=bean.getThreadAllocatedBytes(Thread.currentThread().threadId())-before;need(allocated<=1024&&bake.meshBuilds()==16,"warm 10000 draw lookups bytes="+allocated+" builds="+bake.meshBuilds());System.out.println("[vandorlabs][screen-render] warm PASS 10000draws bytes="+allocated+" retained="+bake.retainedBytes());}
 @SubscribeEvent public static void draw(ScreenEvent.Render.Post event){if(done||!enabled()||!(event.getScreen() instanceof net.minecraft.client.gui.screens.TitleScreen))return;var mc=Minecraft.getInstance();if(mc.getOverlay()!=null)return;if(scenes==null)prepare();var gui=event.getGuiGraphics();gui.flush();com.mojang.blaze3d.systems.RenderSystem.clear(org.lwjgl.opengl.GL11.GL_DEPTH_BUFFER_BIT,Minecraft.ON_OSX);gui.fill(0,0,mc.getWindow().getGuiScaledWidth(),mc.getWindow().getGuiScaledHeight(),0xff202830);gui.flush();var buffers=mc.renderBuffers().bufferSource();if(frames>=4)for(int i=0;i<16;i++){int x=8+i%4*155,y=8+i/4*84;gui.enableScissor(x,y,x+150,y+80);var pose=gui.pose();pose.pushPose();try{pose.translate(x+75,y+40,350);pose.scale(48,-48,48);pose.mulPose(Axis.XP.rotationDegrees(15));pose.mulPose(Axis.YP.rotationDegrees(155));pose.translate(-.5,-.5,-.5);NativeScreenRenderer.renderAt(bake,visuals[i],STATE,NativeScreenRenderProjection.SINGLE,WORLD,OWNERS[i],pose,buffers,0xF000F0,OverlayTexture.NO_OVERLAY);}finally{pose.popPose();}buffers.endBatch();gui.flush();gui.disableScissor();}frames++;capture=frames==4||frames==9;}
 @SubscribeEvent public static void capture(RenderFrameEvent.Post event)throws Exception{if(!capture||done)return;capture=false;var mc=Minecraft.getInstance();try(var image=Screenshot.takeScreenshot(mc.getMainRenderTarget())){int[] ink=new int[16];double scale=mc.getWindow().getGuiScale();for(int i=0;i<16;i++){int left=(int)((8+i%4*155)*scale),top=(int)((8+i/4*84)*scale),width=(int)(150*scale),height=(int)(80*scale);for(int y=0;y<height;y++)for(int x=0;x<width;x++)if((image.getPixelRGBA(left+x,top+y)&0xffffff)!=0x302820)ink[i]++;}String name=frames==4?"screen-render-disabled.png":"screen-render-positive.png";var path=mc.gameDirectory.toPath().resolve("screenshots/"+name);java.nio.file.Files.createDirectories(path.getParent());image.writeToFile(path);if(frames==4){disabled=ink;for(int count:ink)need(count==0,"disabled emitter negative stays empty");}else{need(disabled!=null,"negative capture precedes positive");for(int i=0;i<16;i++)need(ink[i]>100,"actual role draws visible scene="+i+" pixels="+ink[i]);System.out.println("[vandorlabs][screen-render] title PASS 7roles/16scenes actual atlas+direct media/frame shader; disabled negative empty; pixels="+Arrays.toString(ink));done=true;mc.stop();}}}
}
